88	    auto key = std::make_pair(mem_ptr, tensor_size);
89	    const auto &it = registered_cache_mem_.find(key);
90	    if (it != registered_cache_mem_.cend()) {
91	      continue;
92	    }
93	    void *mem_handle = nullptr;
94	    LLM_CHK_STATUS_RET(transfer_engine_->RegisterMem(mem_ptr, tensor_size, mem_type, mem_handle),
95	                       "Failed to register mem");
96	    mems.mem_handles.emplace_back(mem_handle);
97	    mems.mem_addrs.emplace_back(key);
98	    registered_cache_mem_.emplace(key);
99	    LLMLOGI("Register global mem[%p] success, size:%ld, placement:%u, handle:%p, cache_id:%ld", mem_ptr, tensor_size,
100	            cache_desc.placement, mem_handle, cache_id);
101	  }
102	  cache_id_to_mems_[cache_id] = std::move(mems);
103	  return ge::SUCCESS;
104	}
