19	namespace llm {
20	namespace {
21	constexpr uint64_t kMaxBlockSize = 4UL * 1024 * 1024 * 1024;  // 4GB
22	
23	class CopyJob {
24	 public:
25	  explicit CopyJob(aclrtStream stream, uint64_t max_block_size = kMaxBlockSize)
26	      : stream_(stream), max_block_size_(max_block_size) {}
27	  ~CopyJob() = default;
28	
29	  ge::Status AddCopyTask(void *dst, uint64_t dest_max, const void *src, uint64_t count, aclrtMemcpyKind kind) {
30	    if (!NeedCopyAsync(kind, count)) {
31	      if (aclrt_context_ == nullptr) {
32	        LLM_CHK_BOOL_RET_STATUS(aclrtGetCurrentContext(&aclrt_context_) == ACL_ERROR_NONE, ge::FAILED,
33	                                "Failed to get aclrt context");
34	      }
35	      auto fut = pool_.commit([this, dst, dest_max, src, count, kind]() -> ge::Status {
36	        (void)aclrtSetCurrentContext(aclrt_context_);
37	        const auto ret = aclrtMemcpy(dst, dest_max, src, count, kind);
38	        LLM_CHK_BOOL_RET_STATUS(ret == ACL_ERROR_NONE, ge::FAILED, "failed to copy cache, aclrt_ret = 0x%X",
39	                                static_cast<uint32_t>(ret));
40	        return ge::SUCCESS;
41	      });
42	      LLM_CHK_BOOL_RET_STATUS(fut.valid(), ge::FAILED, "Failed to commit copy task");
43	      copy_futs_.emplace_back(std::move(fut));
44	      return ge::SUCCESS;
45	    }
46	    need_sync_ = true;
47	    uint64_t offset = 0;
48	    uint64_t remaining = count;
49	    while (remaining > 0) {
50	      uint64_t size_to_copy = remaining <= max_block_size_ ? remaining : max_block_size_;
51	      auto dst_start = static_cast<uint8_t *>(dst) + offset;
52	      auto src_start = static_cast<const uint8_t *>(src) + offset;
53	      LLM_CHK_ACL_RET(
54	          aclrtMemcpyAsync(dst_start, dest_max, src_start, size_to_copy, ACL_MEMCPY_DEVICE_TO_DEVICE, stream_));
55	      offset += max_block_size_;
56	      remaining -= size_to_copy;
57	    }
58	    return ge::SUCCESS;
59	  }
60	
61	  ge::Status GetResult() {
62	    if (need_sync_) {
63	      LLM_CHK_STATUS_RET(aclrtSynchronizeStream(stream_));
64	    }
65	    for (size_t i = 0U; i < copy_futs_.size(); ++i) {
66	      LLM_CHK_STATUS_RET(copy_futs_[i].get(), "Failed to copy cache, index = %zu", i);
67	    }
68	    return ge::SUCCESS;
69	  }
70	
71	 private:
72	  bool NeedCopyAsync(aclrtMemcpyKind kind, uint64_t count) const {
73	    constexpr uint64_t kMinBlockSize = 2UL * 1024 * 1024;  // 2MB
74	    return (kind == ACL_MEMCPY_DEVICE_TO_DEVICE) && (count >= kMinBlockSize);
75	  }
76	
77	  aclrtStream stream_ = nullptr;
78	  aclrtContext aclrt_context_ = nullptr;
79	  bool need_sync_ = false;
80	  uint64_t max_block_size_ = 0;
81	  LLMThreadPool pool_{"ge_llm_cahm", 4};
82	  std::vector<std::future<ge::Status>> copy_futs_;
83	};
84	
85	void RemoveTensorIndices(const std::unordered_set<uint64_t> &tensor_indices,
86	                         std::unordered_set<uint64_t> &cache_tensor_indices) {
87	  std::unordered_set<uint64_t> remaining_indices;
88	  for (const auto &index : cache_tensor_indices) {
89	    if (tensor_indices.find(index) == tensor_indices.end()) {
90	      remaining_indices.insert(index);
91	    }
92	  }
93	  cache_tensor_indices.swap(remaining_indices);
94	}
95	}  // namespace
