97	const CacheEntry *CacheManager::DoGetCacheEntry(int64_t cache_id) const {
98	  const auto iter = cache_id_to_entry_.find(cache_id);
99	  return (iter == cache_id_to_entry_.cend()) ? nullptr : &iter->second;
100	}
