102	bool CacheManager::GetCacheKey(const std::pair<int64_t, uint64_t> &cache_id_and_batch_index,
103	                               DataCacheKey &cache_key) const {
104	  std::lock_guard<std::mutex> lk(mu_);
105	  const auto iter = cache_id_and_batch_id_to_cache_key_.find(cache_id_and_batch_index);
106	  if (iter != cache_id_and_batch_id_to_cache_key_.end()) {
107	    cache_key = iter->second;
108	    return true;
109	  }
110	  return false;
111	}
