113	bool CacheManager::GetCacheEntry(const int64_t cache_id, CacheEntry &cache_entry) const {
114	  std::lock_guard<std::mutex> lk(mu_);
115	  auto entry = DoGetCacheEntry(cache_id);
116	  bool success = (entry != nullptr);
117	  if (success) {
118	    cache_entry = *entry;
