123	bool CacheManager::GetCacheEntry(const DataCacheKey &cache_key, bool is_prefix, CacheEntry &cache_entry) const {
124	  std::lock_guard<std::mutex> lk(mu_);
125	  auto &cache_key_to_id = is_prefix ? prefix_key_to_id_ : cache_key_to_id_;
126	  const auto iter = cache_key_to_id.find(cache_key);
127	  if (iter == cache_key_to_id.cend()) {
128	    return false;
129	  }
130	  const auto *entry = DoGetCacheEntry(iter->second);
131	  if (entry == nullptr) {
132	    return false;
133	  }
134	  cache_entry = *entry;
135	  return true;
136	}
