138	ge::Status CacheManager::RegisterCacheEntry(int64_t cache_id, const std::vector<CacheKey> &cache_keys,
139	                                            const CacheDesc &cache_desc, std::vector<uintptr_t> &addrs,
140	                                            int64_t tensor_size) {
141	  CacheEntry cache_entry = CreateCacheEntry(cache_desc, addrs, tensor_size);
142	  {
143	    std::lock_guard<std::mutex> lk(mu_);
144	    AddCacheIndices(cache_entry, cache_id, cache_keys);
145	    cache_id_to_entry_[cache_id] = std::move(cache_entry);
146	    LLM_CHK_STATUS_RET(UpdateCacheTable(), "Failed to update cache table");
147	  }
148	  return ge::SUCCESS;
149	}
