151	ge::Status CacheManager::UnregisterCacheEntry(int64_t cache_id) {
152	  std::lock_guard<std::mutex> lk(mu_);
153	  auto iter = cache_id_to_entry_.find(cache_id);
154	  if (iter == cache_id_to_entry_.cend()) {
155	    return ge::SUCCESS;
156	  }
157	  RemoveCacheIndices(cache_id);
158	  cache_id_to_entry_.erase(iter);
159	  LLM_CHK_STATUS_RET(UpdateCacheTable(), "Failed to update cache table");
160	  return ge::SUCCESS;
