171	ge::Status CacheManager::Allocate(int64_t cache_id, const CacheDesc &cache_desc,
172	                                  const std::vector<CacheKey> &cache_keys, Cache &cache) {
173	  LlmMemPool *mem_pool =
174	      (cache_desc.placement == static_cast<uint32_t>(CachePlacement::HOST)) ? host_mem_pool_ : npu_mem_pool_;
175	  LLM_CHK_BOOL_RET_STATUS(mem_pool != nullptr, ge::LLM_FEATURE_NOT_ENABLED, "memory pool is not enabled");
176	  int64_t tensor_size;
177	  LLM_CHK_STATUS_RET(LLMUtils::CalcTensorMemSize(cache_desc.shape, cache_desc.data_type, tensor_size),
178	                     "Failed to calc tensor size");
179	  std::vector<std::shared_ptr<void>> cache_tensors;
180	  std::vector<uintptr_t> tensor_addresses;
181	  tensor_addresses.reserve(cache_desc.num_tensors);
182	  cache_tensors.reserve(cache_desc.num_tensors);
183	  for (uint32_t i = 0U; i < cache_desc.num_tensors; ++i) {
184	    auto tensor_addr = mem_pool->AllocShared(static_cast<size_t>(tensor_size));
185	    if (tensor_addr == nullptr) {
186	      mem_pool->LogPoolState();
187	      LLMLOGE(ge::LLM_OUT_OF_MEMORY, "Failed to allocate memory, size = %ld, index = %u", tensor_size, i);
188	      return ge::LLM_OUT_OF_MEMORY;
189	    }
190	    (void)cache_tensors.emplace_back(tensor_addr);
191	    (void)tensor_addresses.emplace_back(reinterpret_cast<uintptr_t>(tensor_addr.get()));
192	  }
193	  auto cache_entry = CreateCacheEntry(cache_desc, tensor_addresses, tensor_size);
194	  cache_entry.is_owned = true;  // allocated by llm datadist
195	  cache_entry.ext_ref_count = 1;
196	  cache_entry.cache_addrs = cache_tensors;
197	  {
198	    std::lock_guard<std::mutex> lk(mu_);
199	    LLM_CHK_STATUS_RET(CheckCacheKeys(cache_desc, cache_keys), "Check cache_keys failed");
200	    LLM_CHK_BOOL_RET_STATUS(cache_id_to_entry_.find(cache_id) == cache_id_to_entry_.cend(), ge::LLM_PARAM_INVALID,
201	                            "cache_id %ld already exists", cache_id);
202	    AddCacheIndices(cache_entry, cache_id, cache_keys);
203	    cache_id_to_entry_[cache_id] = std::move(cache_entry);
204	    LLM_CHK_STATUS_RET(UpdateCacheTable(), "Failed to update cache table");
205	  }
206	  cache.cache_id = cache_id;
207	  (void)cache.per_device_tensor_addrs.emplace_back(std::move(tensor_addresses));
208	  LLMLOGI("[cache_id:%ld][Allocate] success, num_tensors = %u, shape = %s, placement = %u", cache_id,
209	          cache_desc.num_tensors, hixl::ToString(cache_desc.shape).c_str(), cache_desc.placement);
210	  return ge::SUCCESS;
211	}
212	
213	CacheEntry CacheManager::CreateCacheEntry(const CacheDesc &cache_desc, std::vector<uintptr_t> &addrs,
214	                                          int64_t tensor_size) {
215	  CacheEntry cache_entry{};
216	  cache_entry.cache_addrs.reserve(addrs.size());
217	  for (const auto addr : addrs) {
218	    cache_entry.cache_addrs.emplace_back(std::shared_ptr<void>(ValueToPtr(addr), &NoDelete));
219	  }
220	  cache_entry.tensor_size = static_cast<uint64_t>(tensor_size);
221	  if (cache_desc.cache_mem_type == CacheMemType::BLOCKS) {
222	    cache_entry.batch_size = 1U;
223	    cache_entry.num_blocks = static_cast<uint64_t>(cache_desc.shape.front());
224	    cache_entry.stride = (cache_entry.tensor_size / cache_entry.num_blocks);
225	  } else if (cache_desc.cache_mem_type == CacheMemType::CACHE) {
226	    cache_entry.batch_size = cache_desc.shape.empty() ? 1U : static_cast<uint32_t>(cache_desc.shape.front());
227	    cache_entry.stride = (cache_entry.tensor_size / cache_entry.batch_size);
228	  } else {
229	    cache_entry.batch_size = cache_desc.shape.empty() ? 1U : static_cast<uint32_t>(cache_desc.shape.front());
230	    cache_entry.num_blocks = cache_entry.batch_size;
231	    cache_entry.stride = (cache_entry.tensor_size / cache_entry.batch_size);
232	  }
233	  cache_entry.cache_mem_type = cache_desc.cache_mem_type;
234	  cache_entry.seq_len_dim_index = cache_desc.seq_len_dim_index;
235	  cache_entry.placement = static_cast<CachePlacement>(cache_desc.placement);
236	  cache_entry.remote_accessible = cache_desc.remote_accessible;
237	  return cache_entry;
238	}
239	
240	ge::Status CacheManager::CheckCacheKeys(const CacheDesc &cache_desc, const std::vector<CacheKey> &cache_keys) const {
241	  LLM_CHK_BOOL_RET_STATUS(cache_keys.size() <= static_cast<size_t>(cache_desc.shape.front()), ge::LLM_PARAM_INVALID,
242	                          "Number of cache_keys(%zu) > batch_size (%ld)", cache_keys.size(), cache_desc.shape.front());
243	  std::set<DataCacheKey> data_cache_keys;
244	  for (const auto &cache_key : cache_keys) {
245	    bool is_prefix = false;
246	    auto data_cache_key = CreateDataCacheKey(cache_key, is_prefix);
247	    const auto &key_to_id = is_prefix ? prefix_key_to_id_ : cache_key_to_id_;
248	    const auto it = key_to_id.find(data_cache_key);
249	    LLM_CHK_BOOL_RET_STATUS(it == key_to_id.cend(), ge::LLM_PARAM_INVALID,
250	                            "cache_key (%lu, %lu) already bound to cache_id(%ld), is_prefix = %d", data_cache_key.first,
251	                            data_cache_key.second, it->second, static_cast<int32_t>(is_prefix));
252	    LLM_CHK_BOOL_RET_STATUS(data_cache_keys.emplace(data_cache_key).second, ge::LLM_PARAM_INVALID,
253	                            "multiply identical cache_keys (%lu, %lu) occurred in the request", data_cache_key.first,
254	                            data_cache_key.second);
255	  }
256	  return ge::SUCCESS;
257	}
258	
259	void CacheManager::AddCacheIndices(CacheEntry &cache_entry, int64_t cache_id, const std::vector<CacheKey> &cache_keys) {
260	  uint32_t batch_index = 0U;
261	  for (const auto &cache_key : cache_keys) {
262	    bool is_prefix = false;
263	    auto data_cache_key = CreateDataCacheKey(cache_key, is_prefix);
264	    if (cache_entry.num_blocks > 0U) {
265	      cache_key_to_id_[data_cache_key] = cache_id;
266	    } else if (data_cache_key.first != UINT64_MAX) {
267	      auto &key_to_id = is_prefix ? prefix_key_to_id_ : cache_key_to_id_;
268	      (void)key_to_id.emplace(data_cache_key, cache_id);
269	      cache_entry.id_to_batch_index_and_size[data_cache_key.first] = std::make_pair(batch_index, cache_entry.stride);
270	      cache_id_and_batch_id_to_cache_key_[std::make_pair(cache_id, batch_index)] = data_cache_key;
271	      std::vector<uint64_t> tmp_tensor_indices(cache_entry.cache_addrs.size());
272	      std::iota(tmp_tensor_indices.begin(), tmp_tensor_indices.end(), 0);
273	      std::unordered_set<uint64_t> tensor_indices(tmp_tensor_indices.begin(), tmp_tensor_indices.end());
274	      cache_id_to_tensor_indices_[cache_id] = tensor_indices;
275	      LLMLOGI("[cache_id:%ld][AddCacheIndex] success, cache_key(%lu, %lu) added, batch_index = %u, size = %lu",
276	              cache_id, data_cache_key.first, data_cache_key.second, batch_index, cache_entry.stride);
277	    } else {
278	      // do nothing
279	    }
280	    ++batch_index;
281	  }
282	}
283	
284	void CacheManager::RemoveCacheIndices(int64_t cache_id) {
285	  for (auto it = cache_key_to_id_.begin(); it != cache_key_to_id_.end();) {
286	    if (it->second == cache_id) {
287	      it = cache_key_to_id_.erase(it);
288	    } else {
289	      ++it;
290	    }
291	  }
292	  for (auto it = prefix_key_to_id_.begin(); it != prefix_key_to_id_.end();) {
293	    if (it->second == cache_id) {
294	      it = prefix_key_to_id_.erase(it);
295	    } else {
296	      ++it;
297	    }
298	  }
299	  for (auto it = cache_id_and_batch_id_to_cache_key_.begin(); it != cache_id_and_batch_id_to_cache_key_.end();) {
300	    if (it->first.first == cache_id) {
301	      it = cache_id_and_batch_id_to_cache_key_.erase(it);
302	    } else {
303	      ++it;
304	    }
305	  }
306	  (void)cache_id_to_tensor_indices_.erase(cache_id);
307	}
308	
309	void CacheManager::RemoveBatchIndex(CacheEntry &cache_entry, int64_t cache_id, uint64_t batch_id) {
310	  const auto it = cache_entry.id_to_batch_index_and_size.find(batch_id);
311	  if (it != cache_entry.id_to_batch_index_and_size.cend()) {
312	    (void)cache_id_and_batch_id_to_cache_key_.erase(std::make_pair(cache_id, it->second.first));
313	    (void)cache_entry.id_to_batch_index_and_size.erase(it);
314	  }
315	}
316	
317	DataCacheKey CacheManager::CreateDataCacheKey(const CacheKey &cache_key, bool &is_prefix) {
318	  is_prefix = cache_key.prefix_id != UINT64_MAX;
319	  return is_prefix ? std::make_pair(cache_key.prefix_id, cache_key.model_id)
320	                   : std::make_pair(cache_key.req_id, cache_key.model_id);
321	}
322	
323	ge::Status CacheManager::Deallocate(int64_t cache_id) {
324	  std::lock_guard<std::mutex> lk(mu_);
325	  auto it = cache_id_to_entry_.find(cache_id);
326	  if (it == cache_id_to_entry_.cend()) {
327	    LLMLOGI("[cache_id:%ld][Deallocate] cache_id does not exist", cache_id);
328	    return ge::SUCCESS;
329	  }
330	
331	  auto &cache_entry = it->second;
332	  if (!cache_entry.is_owned) {
333	    LLMLOGI("[cache_id:%ld][Deallocate] cannot deallocate registered cache", cache_id);
334	    return ge::SUCCESS;
335	  }
336	  if (cache_entry.num_blocks > 0U) {
337	    RemoveCacheIndices(cache_id);
338	    (void)cache_id_to_entry_.erase(it);
339	    LLMLOGI("[cache_id:%ld][Deallocate blocks cache] success", cache_id);
340	    LLM_CHK_STATUS_RET(UpdateCacheTable(), "Failed to update cache table");
341	    return ge::SUCCESS;
342	  }
343	  cache_entry.ext_ref_count = 0;
344	  if (cache_entry.id_to_batch_index_and_size.empty()) {
345	    (void)cache_id_to_entry_.erase(it);
346	    LLMLOGI("[cache_id:%ld][Deallocate] success", cache_id);
347	    LLM_CHK_STATUS_RET(UpdateCacheTable(), "Failed to update cache table");
348	  } else {
349	    LLMLOGI("[cache_id:%ld][Deallocate] delayed for that it is still referenced by %zu cache_key(s)", cache_id,
350	            cache_entry.id_to_batch_index_and_size.size());
351	  }
352	  return ge::SUCCESS;
353	}
354	
355	ge::Status CacheManager::RemoveCacheKey(const CacheKey &cache_key) {
356	  bool is_prefix = false;
357	  auto data_cache_key = CreateDataCacheKey(cache_key, is_prefix);
358	  return RemoveCacheKey(data_cache_key, is_prefix);
359	}
360	
361	ge::Status CacheManager::RemoveCacheKey(const DataCacheKey &data_cache_key, bool is_prefix,
362	                                        const std::unordered_set<uint64_t> &tensor_indices) {
363	  auto &key_to_id = is_prefix ? prefix_key_to_id_ : cache_key_to_id_;
364	  std::lock_guard<std::mutex> lk(mu_);
365	  auto it = key_to_id.find(data_cache_key);
366	  if (it == key_to_id.cend()) {
367	    LLMLOGI("[RemoveCacheKey] cache_key (%lu, %lu) does not exist, is_prefix = %d", data_cache_key.first,
368	            data_cache_key.second, static_cast<int32_t>(is_prefix));
369	    return ge::SUCCESS;
370	  }
371	  const auto cache_id = it->second;
372	  auto entry_it = cache_id_to_entry_.find(cache_id);
373	  if (entry_it == cache_id_to_entry_.end()) {
374	    LLMLOGI("[RemoveCacheKey] cache_id %ld not found in entry map, cleaning up stale key_to_id mapping", cache_id);
375	    (void)key_to_id.erase(it);
376	    return ge::SUCCESS;
377	  }
378	  auto &cache_entry = entry_it->second;
379	  if (!cache_entry.is_owned) {
380	    LLMLOGI(
381	        "[cache_id:%ld] [RemoveCacheKey] does not operate on registered cache, "
382	        "cache_key = (%lu, %lu), is_prefix = %d",
383	        cache_id, data_cache_key.first, data_cache_key.second, static_cast<int32_t>(is_prefix));
384	    return ge::SUCCESS;
385	  }
386	  auto &cache_tensor_indices = cache_id_to_tensor_indices_[cache_id];
387	  if (tensor_indices.empty()) {
388	    cache_tensor_indices.clear();
389	  } else {
390	    RemoveTensorIndices(tensor_indices, cache_tensor_indices);
391	    LLMLOGI("[cache_id:%ld] [RemoveCacheKey] already removed num[%zu] tensors, start index is:%lu", cache_id,
392	            tensor_indices.size(), *tensor_indices.begin());
393	  }
394	  if (!cache_tensor_indices.empty()) {
395	    LLMLOGI("[cache_id:%ld] [RemoveCacheKey] There are still %zu tensors that have not been removed", cache_id,
396	            cache_tensor_indices.size());
397	    return ge::SUCCESS;
398	  }
399	  RemoveBatchIndex(cache_entry, cache_id, data_cache_key.first);
400	  (void)key_to_id.erase(it);
401	  LLMLOGI("[cache_id:%ld] [RemoveCacheKey] success, cache_key = (%lu, %lu), is_prefix = %d", cache_id,
402	          data_cache_key.first, data_cache_key.second, static_cast<int32_t>(is_prefix));
403	  if ((cache_entry.ext_ref_count == 0) && cache_entry.id_to_batch_index_and_size.empty()) {
404	    (void)cache_id_to_entry_.erase(cache_id);
405	    LLMLOGI("[cache_id:%ld][Deallocate] success", cache_id);
406	  }
407	  LLM_CHK_STATUS_RET(UpdateCacheTable(), "Failed to update cache table");
408	  return ge::SUCCESS;
409	}
410	
411	ge::Status CacheManager::CopyCache(const CopyCacheParam &copy_cache_param) {
412	  LLMLOGI("CopyCache [%ld->%ld]", copy_cache_param.src_cache_id, copy_cache_param.dst_cache_id);
413	  const auto src_id = copy_cache_param.src_cache_id;
414	  const auto dst_id = copy_cache_param.dst_cache_id;
415	  CacheEntry src_cache_entry;
416	  CacheEntry dst_cache_entry;
417	  LLM_CHK_BOOL_RET_STATUS(GetCacheEntry(src_id, src_cache_entry), ge::LLM_KV_CACHE_NOT_EXIST,
418	                          "[Copy][%ld->%ld] failed, src_cache_id not found", src_id, dst_id);
419	  LLM_CHK_BOOL_RET_STATUS(GetCacheEntry(dst_id, dst_cache_entry), ge::LLM_KV_CACHE_NOT_EXIST,
420	                          "[Copy][%ld->%ld] failed, dst_cache_id not found", src_id, dst_id);
421	  LLM_CHK_BOOL_RET_STATUS(src_cache_entry.cache_addrs.size() == dst_cache_entry.cache_addrs.size(),
422	                          ge::LLM_PARAM_INVALID, "num_tensors mismatches, src_tensor_num = %zu, dst_tensor_num = %zu",
423	                          src_cache_entry.cache_addrs.size(), dst_cache_entry.cache_addrs.size());
424	  if (copy_cache_param.copy_block_infos.empty()) {
425	    return CopyCacheForContinuous(src_cache_entry, dst_cache_entry, copy_cache_param,
426	                                  src_cache_entry.cache_addrs.size());
427	  } else {
428	    return CopyCacheForBlocks(src_cache_entry, dst_cache_entry, copy_cache_param, src_cache_entry.cache_addrs.size());
429	  }
430	}
431	
432	ge::Status CacheManager::CopyCacheForContinuous(const CacheEntry &src_cache_entry, const CacheEntry &dst_cache_entry,
433	                                                const CopyCacheParam &copy_cache_param, size_t per_device_addr_num,
434	                                                size_t device_index) {
435	  const auto src_id = copy_cache_param.src_cache_id;
436	  const auto dst_id = copy_cache_param.dst_cache_id;
437	  uint64_t copy_size;
438	  LLM_CHK_STATUS_RET(CheckCopyParams(src_cache_entry, dst_cache_entry, copy_cache_param, copy_size),
439	                     "[Copy][%ld->%ld] check param failed", src_id, dst_id);
440	  auto src_offset = src_cache_entry.stride * copy_cache_param.src_batch_index + copy_cache_param.offset;
441	  auto dst_offset = dst_cache_entry.stride * copy_cache_param.dst_batch_index + copy_cache_param.offset;
442	  LLMLOGI("[Copy][%ld->%ld] start", src_id, dst_id);
443	  EnsureCopyStream(device_index);
444	  const auto copy_kind = ResolveCopyKind(src_cache_entry.placement, dst_cache_entry.placement);
445	  CopyJob copy_job(copy_streams_[device_index]);
446	  auto begin = device_index * per_device_addr_num;
447	  for (size_t i = 0U; i < per_device_addr_num; ++i) {
448	    auto src_addr = PtrToPtr<void, uint8_t>(src_cache_entry.cache_addrs[begin + i].get()) + src_offset;
449	    auto dst_max = dst_cache_entry.stride - copy_cache_param.offset;
450	    auto dst_addr = PtrToPtr<void, uint8_t>(dst_cache_entry.cache_addrs[begin + i].get()) + dst_offset;
451	    LLM_CHK_STATUS_RET(copy_job.AddCopyTask(dst_addr, dst_max, src_addr, copy_size, copy_kind),
452	                       "[Copy][%ld->%ld] invoke aclrtMemcpy failed, index = %zu", src_id, dst_id, i);
453	  }
454	  LLM_CHK_STATUS_RET(copy_job.GetResult(), "[Copy][%ld->%ld] invoke aclrtSynchronizeStream failed", src_id, dst_id);
455	  LLMLOGI(
456	      "[Copy][%ld->%ld] success, num_tensors = %zu, src_batch_index = %u, "
457	      "dst_batch_index = %u, offset = %lu, size = %ld",
458	      src_id, dst_id, per_device_addr_num, copy_cache_param.src_batch_index, copy_cache_param.dst_batch_index,
459	      copy_cache_param.offset, copy_cache_param.size);
460	  return ge::SUCCESS;
461	}
462	
463	ge::Status CacheManager::CopyCacheForBlocks(const CacheEntry &src_cache_entry, const CacheEntry &dst_cache_entry,
464	                                            const CopyCacheParam &copy_cache_param, size_t per_device_addr_num,
465	                                            size_t device_index) {
466	  const auto src_id = copy_cache_param.src_cache_id;
467	  const auto dst_id = copy_cache_param.dst_cache_id;
468	  LLM_CHK_BOOL_RET_STATUS(src_cache_entry.stride == dst_cache_entry.stride, ge::FAILED,
469	                          "[Copy][%ld->%ld] failed, block_size mismatches, src = %lu, dst = %lu", src_id, dst_id,
470	                          src_cache_entry.stride, dst_cache_entry.stride);
471	  const auto block_size = src_cache_entry.stride;
472	  LLMLOGI("[Copy][%ld->%ld] start", src_id, dst_id);
473	  EnsureCopyStream(device_index);
474	  CopyJob copy_job(copy_streams_[device_index]);
475	  const auto copy_kind = ResolveCopyKind(src_cache_entry.placement, dst_cache_entry.placement);
476	  auto begin = device_index * per_device_addr_num;
477	  for (size_t i = 0U; i < per_device_addr_num; ++i) {
478	    auto src_addr_base = PtrToPtr<void, uint8_t>(src_cache_entry.cache_addrs[begin + i].get());
479	    auto dst_addr_base = PtrToPtr<void, uint8_t>(dst_cache_entry.cache_addrs[begin + i].get());
480	    for (auto &block_index_pair : copy_cache_param.copy_block_infos) {
481	      const auto src_block_index = block_index_pair.first;
482	      const auto dst_block_index = block_index_pair.second;
483	      LLM_CHK_BOOL_RET_STATUS(src_block_index < src_cache_entry.num_blocks, ge::LLM_PARAM_INVALID,
484	                              "src_block_index:%lu out of range [0, %lu)", src_block_index, src_cache_entry.num_blocks);
485	      LLM_CHK_BOOL_RET_STATUS(dst_block_index < dst_cache_entry.num_blocks, ge::LLM_PARAM_INVALID,
486	                              "dst_block_index:%lu out of range [0, %lu)", dst_block_index, src_cache_entry.num_blocks);
487	      auto src_addr = src_addr_base + block_size * src_block_index;
488	      auto dst_addr = dst_addr_base + block_size * dst_block_index;
489	      LLM_CHK_STATUS_RET(copy_job.AddCopyTask(dst_addr, block_size, src_addr, block_size, copy_kind),
490	                         "[Copy][%ld->%ld] invoke aclrtMemcpy failed, index = %zu", src_id, dst_id, i);
491	    }
492	  }
493	  LLM_CHK_STATUS_RET(copy_job.GetResult(), "[Copy][%ld->%ld] invoke aclrtSynchronizeStream failed", src_id, dst_id);
494	  LLMLOGI("[Copy][%ld->%ld] success, num_tensors = %zu, num_blocks = %zu", src_id, dst_id, per_device_addr_num,
495	          copy_cache_param.copy_block_infos.size());
496	  return ge::SUCCESS;
497	}
498	
499	ge::Status CacheManager::CheckCopyParams(const CacheEntry &src_cache_entry, const CacheEntry &dst_cache_entry,
500	                                         const CopyCacheParam &copy_cache_param, uint64_t &copy_size) {
501	  const auto src_batch_size = src_cache_entry.batch_size;
502	  LLM_CHK_BOOL_RET_STATUS(copy_cache_param.src_batch_index < src_batch_size, ge::LLM_PARAM_INVALID,
503	                          "src_batch_index (%u) out of range [0, %u)", copy_cache_param.src_batch_index,
504	                          src_batch_size);
505	  const auto dst_batch_size = dst_cache_entry.batch_size;
506	  LLM_CHK_BOOL_RET_STATUS(copy_cache_param.dst_batch_index < dst_batch_size, ge::LLM_PARAM_INVALID,
507	                          "dst_batch_index (%u) out of range [0, %u)", copy_cache_param.dst_batch_index,
508	                          dst_batch_size);
509	  if (copy_cache_param.offset > 0) {
510	    LLM_CHK_BOOL_RET_STATUS(copy_cache_param.offset < src_cache_entry.stride, ge::LLM_PARAM_INVALID,
511	                            "offset out of range of src cache tensor, offset = %lu, tensor stride = %lu",
512	                            copy_cache_param.offset, src_cache_entry.stride);
513	    LLM_CHK_BOOL_RET_STATUS(copy_cache_param.offset < dst_cache_entry.stride, ge::LLM_PARAM_INVALID,
514	                            "offset out of range of dst cache tensor, offset = %lu, tensor stride = %lu",
515	                            copy_cache_param.offset, dst_cache_entry.stride);
516	  }
517	  copy_size = copy_cache_param.size != -1 ? static_cast<uint64_t>(copy_cache_param.size)
518	                                          : src_cache_entry.stride - copy_cache_param.offset;
519	  LLM_CHK_BOOL_RET_STATUS(copy_size <= (src_cache_entry.stride - copy_cache_param.offset), ge::LLM_PARAM_INVALID,
520	                          "src_tensor out of range, offset = %lu, copy_size = %ld, tensor stride = %lu",
521	                          copy_cache_param.offset, copy_cache_param.size, src_cache_entry.stride);
522	  LLM_CHK_BOOL_RET_STATUS(copy_size <= (dst_cache_entry.stride - copy_cache_param.offset), ge::LLM_PARAM_INVALID,
523	                          "dst_tensor out of range, offset = %lu, copy_size = %ld, tensor stride = %lu, "
524	                          "src tensor stride = %lu",
525	                          copy_cache_param.offset, copy_cache_param.size, dst_cache_entry.stride,
526	                          src_cache_entry.stride);
527	  return ge::SUCCESS;
528	}
529	
530	aclrtMemcpyKind CacheManager::ResolveCopyKind(CachePlacement src_placement, CachePlacement dst_placement) {
531	  return (src_placement == CachePlacement::HOST)
532	             ? ((dst_placement == CachePlacement::HOST) ? ACL_MEMCPY_HOST_TO_HOST : ACL_MEMCPY_HOST_TO_DEVICE)
533	             : ((dst_placement == CachePlacement::HOST) ? ACL_MEMCPY_DEVICE_TO_HOST : ACL_MEMCPY_DEVICE_TO_DEVICE);
534	}
535	
536	void CacheManager::DestroyCopyStream(size_t device_index) {
537	  if (device_index < copy_streams_.size() && (copy_streams_[device_index] != nullptr)) {
538	    LLM_CHK_ACL(aclrtDestroyStream(copy_streams_[device_index]));
539	    copy_streams_[device_index] = nullptr;
540	  }
541	}
542	
543	void CacheManager::Finalize() {
544	  DestroyCopyStream(0U);
545	  cache_access_table_updater_.Finalize();
546	}
547	
548	ge::Status CacheManager::EnsureCopyStream(size_t device_index) {
549	  std::lock_guard<std::mutex> lk(copy_mu_);
550	  if (copy_streams_[device_index] == nullptr) {
551	    LLM_CHK_ACL_RET(aclrtCreateStream(&copy_streams_[device_index]));
552	  }
553	  return ge::SUCCESS;
554	}
555	
556	ge::Status CacheManager::InitCopyStreams(size_t device_num) {
557	  copy_streams_.resize(device_num);
558	  return ge::SUCCESS;
559	}
560	
561	ge::Status CacheManager::Initialize(bool access_remote_cache) {
562	  enable_remote_cache_accessible_ = access_remote_cache;
563	  LLM_CHK_STATUS_RET(cache_access_table_updater_.Initialize(access_remote_cache));
564	  LLM_CHK_ACL_RET(aclrtGetCurrentContext(&aclrt_context_));
565	  copy_streams_.resize(1U);
566	  return ge::SUCCESS;
567	}
568	
569	std::pair<void *, size_t> CacheManager::GetCacheTableBufferAndSize() const {
570	  return cache_access_table_updater_.GetDevBufferAndSize();
571	}
572	
573	ge::Status CacheManager::UpdateCacheTable() {
574	  if (!enable_remote_cache_accessible_) {
575	    return ge::SUCCESS;
576	  }
577	  hixl::TemporaryRtContext with_context(aclrt_context_);
578	  LLM_CHK_ACL_RET(cache_access_table_updater_.UpdateTableBuffer(cache_id_to_entry_, cache_key_to_id_));
579	  return ge::SUCCESS;
580	}
