35	ge::Status ParseMemoryPoolConfig(const std::string &mem_pool_config, size_t &pool_size, size_t &page_shift) {
36	  const std::string &json_str = mem_pool_config;
37	  nlohmann::json json_obj;
38	  try {
39	    json_obj = nlohmann::json::parse(json_str);
40	    LLM_CHK_BOOL_RET_STATUS(json_obj.at("memory_size").is_number_unsigned(), ge::LLM_PARAM_INVALID,
41	                            "memory_size is not an unsigned integer: config = %s", json_str.c_str());
42	    pool_size = json_obj.at("memory_size").get<size_t>();
43	    if (json_obj.contains("page_shift")) {
44	      LLM_CHK_BOOL_RET_STATUS(json_obj.at("page_shift").is_number_unsigned(), ge::LLM_PARAM_INVALID,
45	                              "page_shift is not an unsigned integer: config = %s", json_str.c_str());
46	      page_shift = json_obj.at("page_shift").get<size_t>();
47	      // page_shift valid range is [10, 31)
48	      LLM_CHK_BOOL_RET_STATUS((page_shift >= 10) && (page_shift < 31), ge::LLM_PARAM_INVALID,
49	                              "page_shift (%zu) out of range: [10, 31)", page_shift);
50	    }
51	    LLM_CHK_BOOL_RET_STATUS((pool_size >> page_shift) < std::numeric_limits<uint32_t>::max(), ge::LLM_PARAM_INVALID,
52	                            "memory_size (%zu) with page_shift (%zu) exceeds addressable limit", pool_size, page_shift);
53	  } catch (nlohmann::json::exception &e) {
54	    REPORT_INNER_ERR_MSG("E19999", "Failed to parse memory pool config: %s", json_str.c_str());
55	    LLMLOGE(ge::LLM_PARAM_INVALID, "Failed to parse memory pool config: \"%s\", exception = %s", json_str.c_str(),
56	            e.what());
57	    return ge::LLM_PARAM_INVALID;
58	  }
59	  return ge::SUCCESS;
60	}
