62	ge::Status CheckTensorIndicesContinuous(const std::vector<uint64_t> &tensor_indices) {
63	  if (tensor_indices.empty()) {
64	    return ge::SUCCESS;
65	  }
66	  std::set<uint64_t> unique_elements(tensor_indices.begin(), tensor_indices.end());
67	  LLM_CHK_BOOL_RET_STATUS(unique_elements.size() == tensor_indices.size(), ge::LLM_PARAM_INVALID,
68	                          "tensor_indices is not continuous");
69	  const uint64_t min_element = *std::min_element(unique_elements.begin(), unique_elements.end());
70	  const uint64_t max_element = *std::max_element(unique_elements.begin(), unique_elements.end());
71	  LLM_CHK_BOOL_RET_STATUS((max_element - min_element + 1) == unique_elements.size(), ge::LLM_PARAM_INVALID,
72	                          "tensor_indices is not continuous");
73	  return ge::SUCCESS;
74	}
