76	ge::Status ResolveSwapNumBlocks(int64_t cache_id, CacheManager *cache_manager, uint64_t &num_blocks) {
77	  if (cache_id < 0) {
78	    // Address-only swap path (Python swap_blocks passes cache_id=-1); block indices are
79	    // validated in Python and copy ranges are checked in SwapImpl.
80	    num_blocks = 0U;
81	    return ge::SUCCESS;
82	  }
83	  CacheEntry cache_entry;
84	  LLM_CHK_BOOL_RET_STATUS(cache_manager->GetCacheEntry(cache_id, cache_entry), ge::LLM_KV_CACHE_NOT_EXIST,
85	                          "cache id:%ld not found", cache_id);
86	  num_blocks = cache_entry.num_blocks > 0U ? cache_entry.num_blocks : static_cast<uint64_t>(cache_entry.batch_size);
87	  LLM_CHK_BOOL_RET_STATUS(num_blocks > 0U, ge::LLM_PARAM_INVALID, "cache id:%ld has no blocks", cache_id);
88	  return ge::SUCCESS;
89	}
