91	ge::Status DataCacheEngine::Register(const llm::CacheDesc &cache_desc, const std::vector<CacheKey> &cache_keys,
92	                                     llm::Cache &cache) {
93	  LLM_CHK_BOOL_RET_STATUS(!cache_desc.shape.empty() && (cache_desc.shape.size() < kMaxDimNum), ge::LLM_PARAM_INVALID,
94	                          "Invalid shape: %s, dim_num (%zu) must be in range [1, 33)",
95	                          hixl::ToString(cache_desc.shape).c_str(), cache_desc.shape.size());
96	  LLM_CHECK_GE(cache.per_device_tensor_addrs.size(), 1);
97	  LLM_CHK_BOOL_RET_STATUS(cache_desc.num_tensors == static_cast<uint32_t>(cache.per_device_tensor_addrs[0].size()),
98	                          ge::LLM_PARAM_INVALID, "cache addrs size[%zu] is not equal to num_tensors[%u] of cache_desc",
99	                          cache.per_device_tensor_addrs[0].size(), cache_desc.num_tensors);
100	  std::lock_guard<std::mutex> lock(mu_);
101	  const auto cache_id = cache_id_gen_.fetch_add(1, std::memory_order::memory_order_relaxed);
102	  LLM_CHECK_GE(cache_id, 1);
103	  int64_t tensor_size;
104	  LLM_CHK_STATUS_RET(LLMUtils::CalcTensorMemSize(cache_desc.shape, cache_desc.data_type, tensor_size),
105	                     "Failed to calc tensor size, shape = %s, dtype = %d", hixl::ToString(cache_desc.shape).c_str(),
106	                     static_cast<int32_t>(cache_desc.data_type));
107	  LLMLOGI("[Register] start, placement:%u", static_cast<uint32_t>(cache_desc.placement));
108	  LLM_CHK_STATUS_RET(
109	      comm_mem_manager_->RegisterCacheMem(cache_id, cache_desc, cache.per_device_tensor_addrs[0U], tensor_size),
110	      "Register cache addr failed, cache_id = %ld.", cache_id);
111	  LLM_CHK_STATUS_RET(cache_manager_->RegisterCacheEntry(cache_id, cache_keys, cache_desc,
112	                                                        cache.per_device_tensor_addrs[0U], tensor_size),
113	                     "Register cache entry failed.");
114	  cache.cache_id = cache_id;
115	  LLMLOGI("[cache_id:%ld][Register] success, num_tensors = %u, shape = %s", cache_id, cache_desc.num_tensors,
116	          hixl::ToString(cache_desc.shape).c_str());
117	  return ge::SUCCESS;
118	}
