132	ge::Status DataCacheEngine::PullCache(int64_t cache_id, const CacheKey &cache_key,
133	                                      const PullCacheParam &pull_cache_param) const {
134	  const auto start = std::chrono::steady_clock::now();
135	  // cache_id is local, find local addr by cache_id
136	  CacheEntry cache_entry;
137	  LLM_CHK_BOOL_RET_STATUS(cache_manager_->GetCacheEntry(cache_id, cache_entry), ge::LLM_KV_CACHE_NOT_EXIST,
138	                          "cache id:%ld not found", cache_id);
139	  LLM_CHK_STATUS_RET(CheckParam(cache_entry, pull_cache_param), "[cache_id:%ld] check param failed", cache_id);
140	  LLMLOGI("pull cache with tensor num per layer:%lu.", pull_cache_param.tensor_num_per_layer);
141	  const auto entity = comm_entity_manager_->GetEntityByRemoteClusterId(cache_key.prompt_cluster_id);
142	  LLM_CHK_BOOL_RET_STATUS(entity != nullptr, ge::LLM_NOT_YET_LINK,
143	                          "current cluster is not linked with remote cluster:%lu", cache_key.prompt_cluster_id);
144	  std::lock_guard<std::mutex> pull_lock(entity->GetPullMutex());
145	  // in case of entity is erased here, can not delete.
146	  LLM_CHK_BOOL_RET_STATUS((entity->GetCurState() != FsmState::FSM_DESTROYED_STATE), ge::LLM_NOT_YET_LINK,
147	                          "current cluster is not linked with remote cluster:%lu", cache_key.prompt_cluster_id);
148	  LLMLOGI("Get lock cost:%ld us.",
149	          std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - start).count());
150	  hixl::TemporaryRtContext with_context(aclrt_context_);
151	  LLM_CHK_BOOL_RET_STATUS(entity->CheckEntityInfo(), ge::LLM_NOT_YET_LINK,
152	                          "pull cache must wait until the query_register_mem_status return ok");
153	  if (access_remote_cache_) {
154	    DataTransferClient client(*entity, nullptr);
155	    LLM_CHK_STATUS_RET(client.PullCacheByGet(cache_entry, cache_key, pull_cache_param, sync_cache_timeout_));
156	    LLMLOGI(
157	        "[PullCache] success, cache_id = %ld, num_tensors = %zu, stride = %lu, "
158	        "pull_size = %ld, local_block_cnt = %zu, remote_block_cnt = %zu",
159	        cache_id, cache_entry.cache_addrs.size(), cache_entry.stride, pull_cache_param.size,
160	        pull_cache_param.decoder_blocks.size(), pull_cache_param.prompt_blocks.size());
161	    return ge::SUCCESS;
162	  }
163	  LLM_DISMISSABLE_GUARD(abort_stream, [this]() -> void { LLM_CHK_ACL(aclrtStreamAbort(req_stream_)); });
164	  entity->ClearResponseFlags();
165	  if (cache_entry.placement == CachePlacement::HOST) {
166	    LLM_CHK_BOOL_RET_STATUS(npu_pool_memory_ != nullptr, ge::LLM_PARAM_INVALID, "Device memory pool is not enabled.");
167	    D2HDataTransferClient client(*entity, req_stream_);
168	    LLM_CHK_STATUS_RET(client.PullCache(cache_entry, cache_key, pull_cache_param, sync_cache_timeout_),
169	                       "Failed to pull kv from remote cluster:%lu", cache_key.prompt_cluster_id);
170	    LLM_DISMISS_GUARD(abort_stream);
171	    return ge::SUCCESS;
172	  }
173	
174	  DataTransferClient client(*entity, req_stream_);
175	  LLM_CHK_STATUS_RET(client.PullCache(cache_entry, cache_key, pull_cache_param, sync_cache_timeout_),
176	                     "Failed to pull kv from remote cluster:%lu", cache_key.prompt_cluster_id);
177	  LLM_DISMISS_GUARD(abort_stream);
178	  return ge::SUCCESS;
179	}
