181	ge::Status DataCacheEngine::SwapBlocks(const Cache &src, const Cache &dst, const uint64_t block_size,
182	                                       const uint32_t type,
183	                                       const std::vector<std::pair<int64_t, int64_t>> &block_mapping) const {
184	  const bool src_by_addr = src.cache_id < 0;
185	  const bool dst_by_addr = dst.cache_id < 0;
186	  LLM_CHK_BOOL_RET_STATUS(src_by_addr == dst_by_addr, ge::LLM_PARAM_INVALID,
187	                          "src/dst cache_id must both be registered(>=0) or both be address-only(-1), "
188	                          "got src:%ld dst:%ld",
189	                          src.cache_id, dst.cache_id);
190	
191	  uint64_t src_num_blocks = 0U;
192	  uint64_t dst_num_blocks = 0U;
193	  LLM_CHK_STATUS_RET(ResolveSwapNumBlocks(src.cache_id, cache_manager_, src_num_blocks),
194	                     "resolve src num blocks failed");
195	  LLM_CHK_STATUS_RET(ResolveSwapNumBlocks(dst.cache_id, cache_manager_, dst_num_blocks),
196	                     "resolve dst num blocks failed");
197	
198	  SwapImpl swap_impl(device_id_);
199	  LLM_CHK_STATUS_RET(swap_impl.SwapBlocksV2(src, dst, block_size, type, block_mapping, src_num_blocks, dst_num_blocks));
200	  return ge::SUCCESS;
201	}
