275	ge::Status DataCacheEngine::InitializeDeviceMemoryPool(const std::map<ge::AscendString, ge::AscendString> &options) {
276	  const auto it = options.find(LLM_OPTION_MEM_POOL_CONFIG);
277	  if (it == options.cend()) {
278	    LLMLOGI("memory pool is not enabled");
279	    return ge::SUCCESS;
280	  }
281	  const std::string &json_str = it->second.GetString();
282	  size_t page_shift = 16U;  // 64KB by default
283	  LLM_CHK_STATUS_RET(ParseMemoryPoolConfig(json_str, npu_pool_size_, page_shift), "parse %s failed",
284	                     LLM_OPTION_MEM_POOL_CONFIG);
285	  ScalableConfig config{};
286	  config.page_idem_num = page_shift;
287	  config.page_mem_size_total_threshold = npu_pool_size_;
288	  npu_mem_pool_ = MakeUnique<LlmMemPool>(config);
289	  LLM_CHECK_NOTNULL(npu_mem_pool_, "Failed to create memory pool");
290	  LLM_CHK_BOOL_RET_STATUS(
291	      aclrtMalloc(&npu_pool_memory_, npu_pool_size_, ACL_MEM_TYPE_HIGH_BAND_WIDTH) == ACL_ERROR_NONE,
292	      ge::LLM_OUT_OF_MEMORY, "Failed to allocate memory for memory_pool, config = %s", json_str.c_str());
293	  LLM_CHK_STATUS_RET(npu_mem_pool_->Initialize(npu_pool_memory_, npu_pool_size_),
294	                     "Failed to initialize memory pool, config = %s", json_str.c_str());
295	  LLM_CHK_STATUS_RET(GlobalMemManager::GetInstance().RegisterMem(npu_pool_memory_, npu_pool_size_,
296	                                                                 CommMemType::COMM_MEM_TYPE_DEVICE, npu_pool_handle_));
297	  cache_manager_->SetNpuMemPool(npu_mem_pool_.get());
298	  LLMLOGI("npu memory_size = %lu B, page_shift = %zu, page_size = %lu B", npu_pool_size_, page_shift,
299	          (1UL << page_shift));
300	  return ge::SUCCESS;
301	}
