304	  const auto it = options.find(LLM_OPTION_HOST_MEM_POOL_CONFIG);
305	  if (it == options.cend()) {
306	    LLMLOGI("host memory pool is not enabled");
307	    return ge::SUCCESS;
308	  }
309	  const std::string &json_str = it->second.GetString();
310	  size_t page_shift = 16U;  // 64KB by default
311	  size_t host_pool_size = 0UL;
312	  LLM_CHK_STATUS_RET(ParseMemoryPoolConfig(json_str, host_pool_size, page_shift), "parse %s failed",
313	                     LLM_OPTION_HOST_MEM_POOL_CONFIG);
314	  ScalableConfig config{};
315	  config.page_idem_num = page_shift;
316	  config.page_mem_size_total_threshold = host_pool_size;
317	  host_mem_pool_ = MakeUnique<LlmMemPool>(config);
