320	  LLM_CHK_STATUS_RET(host_mem_pool_->Initialize(host_pool_memory_, host_pool_size),
321	                     "Failed to initialize host memory pool, config = %s", json_str.c_str());
322	  LLM_CHK_STATUS_RET(GlobalMemManager::GetInstance().RegisterMem(host_pool_memory_, host_pool_size, COMM_MEM_TYPE_HOST,
323	                                                                 host_pool_handle_));
324	  cache_manager_->SetHostMemPool(host_mem_pool_.get());
325	  LLMLOGI("host memory_size = %lu B, page_shift = %zu, page_size = %lu B", host_pool_size, page_shift,
326	          (1UL << page_shift));
327	  return ge::SUCCESS;
328	}
