379	ge::Status DataCacheEngine::CheckParam(const CacheEntry &cache_entry, const PullCacheParam &pull_cache_param) {
380	  LLM_CHK_BOOL_RET_STATUS(pull_cache_param.batch_index < cache_entry.batch_size, ge::LLM_PARAM_INVALID,
381	                          "dst_batch_index:%u out of range [0, %u)", pull_cache_param.batch_index,
382	                          cache_entry.batch_size);
383	  if (pull_cache_param.decoder_blocks.empty()) {
384	    LLM_CHK_BOOL_RET_STATUS(cache_entry.num_blocks == 0 || cache_entry.cache_mem_type == CacheMemType::MIX,
385	                            ge::LLM_PARAM_INVALID, "check failed, request expect local cache is non-blocks");
386	    LLM_CHK_BOOL_RET_STATUS(
387	        (pull_cache_param.size < 0) || (static_cast<uint64_t>(pull_cache_param.size) <= cache_entry.stride),
388	        ge::LLM_PARAM_INVALID, "pull_size(%ld) > cache stride(%lu)", pull_cache_param.size, cache_entry.stride);
389	  } else {
390	    LLM_CHK_BOOL_RET_STATUS(cache_entry.num_blocks > 0, ge::LLM_PARAM_INVALID,
391	                            "check failed, request expect local cache is blocks");
392	  }
393	  if ((cache_entry.placement == CachePlacement::HOST) && (cache_entry.cache_mem_type == CacheMemType::BLOCKS)) {
394	    for (const auto block_index : pull_cache_param.decoder_blocks) {
395	      LLM_CHK_BOOL_RET_STATUS(block_index < cache_entry.num_blocks, ge::LLM_PARAM_INVALID,
396	                              "local block index out of bound, index = %lu, num_blocks = %lu", block_index,
397	                              cache_entry.num_blocks);
398	    }
399	    LLM_CHK_BOOL_RET_STATUS(pull_cache_param.prompt_blocks.empty() ||
400	                                (pull_cache_param.decoder_blocks.size() == pull_cache_param.prompt_blocks.size()),
401	                            ge::LLM_PARAM_INVALID,
402	                            "check failed, src_block_index.size() = %zu, dst_block_index.size() = %zu",
403	                            pull_cache_param.prompt_blocks.size(), pull_cache_param.decoder_blocks.size());
404	  }
405	  LLM_CHK_BOOL_RET_STATUS(pull_cache_param.tensor_num_per_layer >= 1, ge::LLM_PARAM_INVALID,
406	                          "check failed, tensor_num_per_layer expect [1, %lu]", cache_entry.cache_addrs.size());
407	  LLM_CHK_STATUS_RET(CheckTensorIndices(cache_entry, pull_cache_param), "tensor_indices is invalid");
408	  return ge::SUCCESS;
409	}
410	
411	ge::Status DataCacheEngine::CheckTensorIndices(const CacheEntry &cache_entry, const PullCacheParam &pull_cache_param) {
412	  // 此处cache_entry是pull的dst
413	  const size_t remainder = cache_entry.cache_addrs.size() % pull_cache_param.tensor_num_per_layer;
414	  if ((!pull_cache_param.src_tensor_indices.empty()) || (!pull_cache_param.dst_tensor_indices.empty())) {
415	    LLM_CHK_BOOL_RET_STATUS(remainder == 0U, ge::LLM_PARAM_INVALID,
416	                            "When using layer wise transfer, the tensor_num [%zu] of caches must be a multiple of "
417	                            "tensor_num_per_layer[%lu].",
418	                            cache_entry.cache_addrs.size(), pull_cache_param.tensor_num_per_layer);
419	  }
420	  LLM_CHK_STATUS_RET(CheckTensorIndicesContinuous(pull_cache_param.src_tensor_indices),
421	                     "src_tensor_indices is not continuous");
422	  LLM_CHK_STATUS_RET(CheckTensorIndicesContinuous(pull_cache_param.dst_tensor_indices),
423	                     "dst_tensor_indices is not continuous");
424	
425	  if (!pull_cache_param.dst_tensor_indices.empty()) {
426	    LLM_CHK_BOOL_RET_STATUS(pull_cache_param.dst_tensor_indices.size() <= cache_entry.cache_addrs.size(),
427	                            ge::LLM_PARAM_INVALID, "dst_tensor_indices size[%zu] is out of range[0, %zu]",
428	                            pull_cache_param.dst_tensor_indices.size(), cache_entry.cache_addrs.size());
429	    LLM_CHK_BOOL_RET_STATUS((pull_cache_param.dst_tensor_indices.front() < cache_entry.cache_addrs.size()) &&
430	                                (pull_cache_param.dst_tensor_indices.back() < cache_entry.cache_addrs.size()),
431	                            ge::LLM_PARAM_INVALID,
432	                            "dst_tensor_indices start index[%lu] or end index[%lu] is out of range[0, %zu)",
433	                            pull_cache_param.dst_tensor_indices.front(), pull_cache_param.dst_tensor_indices.back(),
434	                            cache_entry.cache_addrs.size());
435	  }
436	  if ((!pull_cache_param.src_tensor_indices.empty()) && (!pull_cache_param.dst_tensor_indices.empty())) {
437	    LLM_CHK_BOOL_RET_STATUS(pull_cache_param.src_tensor_indices.size() == pull_cache_param.dst_tensor_indices.size(),
438	                            ge::LLM_PARAM_INVALID,
439	                            "src_tensor_indices size[%zu] is not match dst_tensor_indices size[%zu]",
440	                            pull_cache_param.src_tensor_indices.size(), pull_cache_param.dst_tensor_indices.size());
441	  } else if (!pull_cache_param.src_tensor_indices.empty()) {
442	    LLM_CHK_BOOL_RET_STATUS(pull_cache_param.src_tensor_indices.size() == cache_entry.cache_addrs.size(),
443	                            ge::LLM_PARAM_INVALID,
444	                            "src_tensor_indices size[%zu] is not match dst_num_tensors size[%zu]",
445	                            pull_cache_param.src_tensor_indices.size(), cache_entry.cache_addrs.size());
446	  } else {
447	    // default
448	  }
449	  return ge::SUCCESS;
450	}
451	
452	ge::Status DataCacheEngine::TransferCache(const uint64_t task_id, const TransferCacheConfig &transfer_cache_config,
453	                                          const TransferBlockConfig &transfer_block_config) {
454	  // cache_id is local, find local addr by cache_id
455	  CacheEntry cache_entry;
456	  LLM_CHK_BOOL_RET_STATUS(cache_manager_->GetCacheEntry(transfer_cache_config.src_cache_id, cache_entry),
457	                          ge::LLM_KV_CACHE_NOT_EXIST, "cache id:%ld not found", transfer_cache_config.src_cache_id);
458	
459	  const auto entity = comm_entity_manager_->GetEntityByRemoteClusterId(transfer_cache_config.cluster_id);
460	  LLM_CHK_BOOL_RET_STATUS(entity != nullptr, ge::LLM_NOT_YET_LINK,
461	                          "current cluster is not linked with remote cluster:%lu", transfer_cache_config.cluster_id);
462	  std::lock_guard<std::mutex> pull_lock(entity->GetPullMutex());
463	  // in case of entity is erased here, can not delete.
464	  LLM_CHK_BOOL_RET_STATUS((entity->GetCurState() != FsmState::FSM_DESTROYED_STATE), ge::LLM_NOT_YET_LINK,
465	                          "current cluster is not linked with remote cluster:%lu", transfer_cache_config.cluster_id);
466	  LLM_CHK_BOOL_RET_STATUS(entity->CheckEntityInfo(), ge::LLM_NOT_YET_LINK,
467	                          "transfer cache must wait until the query_register_mem_status return ok");
468	  LLM_CHK_BOOL_RET_STATUS(transfer_cache_config.tensor_num_per_layer >= 1, ge::LLM_PARAM_INVALID,
469	                          "check failed, tensor_num_per_layer expect [1, %lu]", cache_entry.cache_addrs.size());
470	  LLMLOGI("Transfer cache with tensor num per layer:%lu.", transfer_cache_config.tensor_num_per_layer);
471	  hixl::TemporaryRtContext with_context(aclrt_context_);
472	  aclError ret = ACL_ERROR_NONE;
473	  std::call_once(create_stream_once_flag_, [&ret, this]() {
474	    ret = aclrtCreateStreamWithConfig(&transfer_stream_, 0, ACL_STREAM_FAST_LAUNCH | ACL_STREAM_FAST_SYNC);
475	  });
476	  LLM_ASSERT_RT_OK(ret, "create transfer stream failed");
477	  LLM_ASSERT_NOTNULL(transfer_stream_, "transfer stream is nullptr");
478	  LLM_DISMISSABLE_GUARD(abort_stream, [this]() -> void { LLM_CHK_ACL(aclrtStreamAbort(transfer_stream_)); });
479	  LayerWiseTransferJob layer_wise_transfer_job(*entity, transfer_stream_);
480	  LLM_CHK_STATUS_RET(layer_wise_transfer_job.TransferCache(cache_entry, transfer_cache_config, transfer_block_config,
481	                                                           sync_cache_timeout_, access_remote_cache_),
482	                     "task:%lu of cluster:%lu transfer cache of layer[%lu] failed", task_id,
483	                     transfer_cache_config.cluster_id, transfer_cache_config.layer_index);
484	  LLM_DISMISS_GUARD(abort_stream);
485	  return ge::SUCCESS;
486	}
487	}  // namespace llm
